# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the chat agent's knowledge of how to use this app ("show me how to use /script"),
#          as a deferred pydantic-ai capability with no tools: the model sees one line until
#          an app question comes up, then loads the whole guide (services/ui/guide.md, the
#          words) with every slash command and key added from the code (commands.py,
#          shortcuts.py), so those lists can't go stale. Read from disk on every load (no
#          cache): an edit to guide.md applies to the next chat that loads it.
# Usage: Session.ask passes app_guide_capability on each chat run, so pkgs/ds/ai (and
#        `ds ai eval`) are not changed; agents.py lists it in the debug panel's Agents tab.
# ---------------------------------------------------------------------------
from __future__ import annotations

import re
from pathlib import Path

from ds.util.text import clean_f_str
from pydantic_ai.capabilities import Capability

from ui.commands import SLASH
from ui.shortcuts import Shortcut

GUIDE = Path(__file__).resolve().parents[1] / "guide.md"
# notes to whoever edits the guide (attribution, what the file is for): not for the model
_COMMENT = re.compile(r"<!--.*?-->\s*", re.DOTALL)

_RULES = clean_f_str("""
    This is the guide to the app the user is talking to you in: delulu-smash, a desktop workbench (chat,
    results, Python cells, variables). Use it for questions about using the app, not about Smash the game.
    - Answer from this guide only. If it doesn't cover something, say the guide doesn't cover it; never
      invent a command, key or feature.
    - Show what to type as code, as the guide does: the exact command or key, then what the user will see.
      Keep it short: the steps for what was asked, not the whole section.
    - You can't run slash commands, press keys or change the app: the user types them in the chat box.
    """)
MISSING = "(The guide file is missing: only the lists below are known. Say so if they don't answer the question.)"


def slash_table() -> str:
    """Every slash command, one per line: what is typed, then what it does."""
    return "\n".join(
        f"/{name}" + (f" <{command.takes}>" if command.takes else "") + f"  {command.group}: {command.title}"
        for name, command in SLASH.items()
    )


def keys_table() -> str:
    """Every keyboard shortcut, one per line: keys, where they work, what they do."""
    return "\n".join(f"{row.keys}  ({row.where})  {row.what}" for row in (shortcut.value for shortcut in Shortcut))


def guide_text() -> str:
    """guide.md without its HTML comments; MISSING when it can't be read."""
    try:
        text = GUIDE.read_text(encoding="utf-8")
    except OSError:
        return MISSING
    return _COMMENT.sub("", text).strip()


def instructions() -> str:
    """What the model gets on loading the capability: the rules, the guide, the live lists."""
    return "\n\n".join(
        [
            _RULES,
            guide_text(),
            "## Every slash command (typed in the chat box)",
            slash_table(),
            "## Every keyboard shortcut: keys (where they work) what they do",
            keys_table(),
        ]
    )


app_guide_capability = Capability(
    id="app_guide",
    description=" ".join(
        [
            "How to use this app (delulu-smash), eg 'how do I use /script?', 'what key opens Python?':",
            "panels and keys, slash commands, widgets, @ variables, /assign, /script, Python cells, fixes.",
        ]
    ),
    # a function: called when the model loads it, so the guide is read then
    instructions=instructions,
    # deferred, as the Smash capabilities: nothing but the description until an app question
    defer_loading=True,
)
